<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advanced SCORM Report</title>
<style>body{font-family:Arial;background:#f4f6f8;margin:0}main{max-width:1250px;margin:auto;padding:28px}table{width:100%;border-collapse:collapse;background:white}th,td{padding:10px;border:1px solid #ddd;text-align:left}form{background:white;padding:15px;margin-bottom:15px}select,button{padding:8px}</style></head><body><main>
<p><a href="<?= site_url('dashboard') ?>">← Dashboard</a></p><h1>Advanced SCORM tracking</h1>
<form method="get"><select name="com_id"><option value="">All companies</option><?php foreach($companies as $c): ?><option value="<?= esc($c['com_id']) ?>" <?= (string)$filters['com_id']===(string)$c['com_id']?'selected':'' ?>><?= esc($c['com_code'].' '.$c['com_name_eng']) ?></option><?php endforeach ?></select>
<select name="cos_id"><option value="">All courses</option><?php foreach($courses as $c): ?><option value="<?= esc($c['cos_id']) ?>" <?= (string)$filters['cos_id']===(string)$c['cos_id']?'selected':'' ?>><?= esc($c['ccode'].' '.$c['cname_eng']) ?></option><?php endforeach ?></select><button>Filter</button> <a href="<?= site_url('report/scormTracking/export').'?'.http_build_query($filters) ?>">Export XLSX</a></form>
<table><tr><th>Learner</th><th>Course</th><th>Lesson</th><th>SCORM</th><th>Status</th><th>Score</th><th>Location</th><th>Session time</th><th>Values</th></tr>
<?php foreach($rows as $r): ?><tr><td><?= esc($r['emp_c'].' '.$r['learner_name']) ?></td><td><?= esc($r['ccode'].' '.$r['course_title']) ?></td><td><?= esc($r['lesson_title']) ?></td><td><?= esc($r['scm_id']) ?></td><td><?= esc($r['status']) ?></td><td><?= esc($r['score']) ?></td><td><?= esc($r['location']) ?></td><td><?= esc($r['session_time']) ?></td><td><?= esc($r['updated_values']) ?></td></tr><?php endforeach ?></table>
</main></body></html>
